"""Run from app folder AFTER patch_heal2.py. Heal v3: AI confidence is capped at 85 (a query that runs proves syntax, not correctness). Backup made; idempotent."""
import shutil, sys, time
P = "agent/heal.py"
PAIRS = [('            if test.get("ok"):\n                conf = min(100, conf + 10) if test["n"] else min(conf, 55)\n                why.append("example SQL ran on the client\'s data" + (f" and returned {test[\'n\']} row(s)" if test["n"] else " but returned no rows"))\n', '            if test.get("ok"):\n                conf = min(85, conf + 10) if test["n"] else min(conf, 55)\n                why.append("example SQL ran on the client\'s data" + (f" and returned {test[\'n\']} row(s)" if test["n"] else " but returned no rows"))\n'), ('                            conf = max(0, min(100, int(d2.get("confidence") or 0))) if str(d2.get("confidence", "")).strip().isdigit() else conf\n                            conf = min(100, conf + 10) if t2["n"] else min(conf, 55)\n                            why.append("first example failed (%s); corrected using the real columns and it ran OK" % first_err[:70])\n', '                            conf = max(0, min(100, int(d2.get("confidence") or 0))) if str(d2.get("confidence", "")).strip().isdigit() else conf\n                            conf = min(85, conf + 10) if t2["n"] else min(conf, 55)\n                            why.append("first example failed (%s); corrected using the real columns and it ran OK" % first_err[:70])\n'), ('                    why.append("example SQL failed when tested and could not be corrected: " + first_err[:120])\n    if not rule:\n', '                    why.append("example SQL failed when tested and could not be corrected: " + first_err[:120])\n    conf = min(conf, 85)      # a query that runs proves syntax, not correctness - never show 100%\n    if not rule:\n')]
s = open(P, encoding="utf-8").read()
if "never show 100" in s: print("ALREADY APPLIED"); sys.exit(0)
for i, (a, b) in enumerate(PAIRS, 1):
    if s.count(a) != 1: print(f"anchor {i} found {s.count(a)}x. Nothing changed (apply patch_heal2.py first)."); sys.exit(1)
    s = s.replace(a, b)
shutil.copy2(P, P + ".bak-" + time.strftime("%Y%m%d-%H%M%S")); open(P, "w", encoding="utf-8").write(s); print("APPLIED")
